let P,projects=[],mode=localStorage.getItem('jbp-mode')||'pro',page=typeof location!=='undefined'&&['video','shots','script','writing'].includes(new URLSearchParams(location.search).get('tool'))?new URLSearchParams(location.search).get('tool'):'home',selected=null,linkFrom=null,filter='all',search='',history=[],future=[],saveTimer,saveChain=Promise.resolve(),playback=null,renderJob=null,exporting=false,uiBusy=false;
const icons={text:'▤',character:'♧',scene:'◫',prop:'◇',image:'▧',video:'▷',audio:'♫',output:'▣'};let cloudAccount=null,cloudList=[],cloudError='';let recording=null,requestingMic=false;let toastTimer;let uiRevision=0,preparingPlay=false;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
let saveRevision=0,savedRevision=0,saveError='';
function saveLabel(){return saveError?'保存失败，请导出备份':savedRevision<saveRevision?'保存中…':'已保存在此浏览器'}
function paintSaveStatus(){const label=$('#saveStatus');if(label)label.textContent=saveLabel()}
function persistSnapshot(copy,revision){
  const pending=saveChain.catch(()=>{}).then(()=>DB.put(copy)).then(()=>{
    savedRevision=Math.max(savedRevision,revision);
    if(typeof AssetAudit!=='undefined')AssetAudit.report(copy).catch(()=>{});
    if(revision===saveRevision)saveError='';
    paintSaveStatus();
  }).catch(error=>{
    if(revision===saveRevision)saveError=error.message||'浏览器存储不可用';
    paintSaveStatus();
    toast('保存失败，请立即导出项目备份：'+error.message);
    throw error;
  });
  saveChain=pending;
  pending.catch(()=>{});
  return pending;
}
function enforceAdministratorRules(){const frozen=administratorFrozen.get(P.id);if(frozen)P.adminAssetControls=structuredClone(frozen);else if(P.adminAssetControls)administratorFrozen.set(P.id,structuredClone(P.adminAssetControls));const rules=administratorRules.get(P.id);if(rules)AssetControls.applyControls(P,rules);if(AssetControls.enforceControls(P))toast('资产已被管理员锁定或删除，修改未应用')}
function queueSave(){enforceAdministratorRules();P.updated=Date.now();const revision=++saveRevision;saveError='';paintSaveStatus();clearTimeout(saveTimer);const copy=structuredClone(P);saveTimer=setTimeout(()=>{saveTimer=null;persistSnapshot(copy,revision)},220)}
async function flush(){enforceAdministratorRules();clearTimeout(saveTimer);saveTimer=null;const copy=structuredClone(P),revision=saveRevision;return persistSnapshot(copy,revision)}
function checkpoint(){history.push(structuredClone(P));if(history.length>25)history.shift();future=[]}
