function blankSeed(){let p=C.project('三星堆 · 三千年的回响');p.script='第一集\n1-1 夜 内 考古实验室\n人物：杜宇、张教授\n△灯光落在青铜面具上，杜宇缓缓伸手，指尖触碰面具。\n杜宇：你是不是，一直在等我？\n△面具的眼睛忽然亮起，远处传来女子的声音。\n郫瑶（画外）：三千年了，你终于回来了。';p.shots=C.parseScript(p.script);let a=C.node('text',30,60),b=C.node('character',320,40),c=C.node('scene',320,330),d=C.node('image',620,120),e=C.node('video',920,120);a.prompt=p.script;p.nodes=[a,b,c,d,e];C.connect(p,a.id,d.id);C.connect(p,b.id,d.id);C.connect(p,c.id,d.id);C.connect(p,d.id,e.id);return p}
async function boot({strict=false}={}){try{projects=await DB.list();let id=(typeof location!=='undefined'&&new URLSearchParams(location.search).get('project'))||localStorage.getItem('jbp-active');P=projects.find(p=>p.id===id)||projects[0];if(!P){P=blankSeed();try{const old=typeof Accounts!=='undefined'&&Accounts.current()?null:JSON.parse(localStorage.getItem('jbp-project'));if(old){P.title=old.title||P.title;P.script=old.script||P.script;P.shots=C.parseScript(P.script);P.nodes.find(n=>n.type==='text').prompt=P.script;for(const a of old.assets||[])if(a.src)P.assets.push({id:C.uid(),name:a.name,type:a.type||'角色',kind:'image',src:a.src,created:Date.now(),locked:false,tags:'',description:''})}}catch{}await DB.put(P);projects=[P]}for(const t of P.tasks)if(t.status==='running'||t.status==='queued')t.status='interrupted';localStorage.setItem('jbp-active',P.id);render();Cloud.me().then(r=>{cloudAccount=r.user;syncHeader();const avatar=$('.avatar');if(avatar){avatar.textContent=cloudAccount.name.slice(0,1);avatar.title=cloudAccount.email}}).catch(e=>cloudError=e.message)}catch(e){if(strict)throw e;$('#main').innerHTML=`<div class="page"><h2>浏览器存储不可用</h2><p>${E(e.message)}</p><p>请使用允许 IndexedDB 的正常浏览器窗口打开。</p></div>`}}
function homePage(){const list=projects.map(p=>p.id===P.id?P:p).sort((a,b)=>b.updated-a.updated);$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="hero custom-hero"><small>YOUR NEXT STORY STARTS HERE</small><h1 style="margin-top:14px">好故事，值得被看见。</h1><p class="muted">从文字走向画面。两个工作模式，共用一套项目资产。</p><div class="row wrap">${button('＋ 新建项目','new-project','','primary')}${button('导入剧本 · 拆分镜头','script-import')}${button('继续创作 →','page',`data-page="${mode==='pro'?'canvas':'video'}"`)}${button('导入项目','import')}${button('备份当前项目','export')}</div></div><div class="row"><h3>项目空间</h3><small>${list.length} 个项目 · 此浏览器保存</small></div><div class="asset-grid">${list.map(p=>`<div class="card"><small>${p.id===P.id?'● 当前项目':'LOCAL PROJECT'}</small><h3>${E(p.title)}</h3><p class="muted">${p.assets.length} 个资产 / ${p.shots.length} 个分镜 / ${p.clips.length} 个片段</p><small>${new Date(p.updated).toLocaleString('zh-CN')}</small><div class="row wrap" style="margin-top:18px">${button('打开','open-project',`data-id="${p.id}"`)}${button('复制','duplicate-project',`data-id="${p.id}"`)}${button('删除','delete-project',`data-id="${p.id}"`,'danger')}</div></div>`).join('')}</div><div class="notice">上传真实图片、视频和音频，可以编辑分镜、制作时间线预演、导出分镜图与字幕。AI 内容生成需另接模型服务；任务队列会明确显示“等待服务”，不会伪造完成结果。</div></div>`)}
function scriptPage(){let eps=P.episodes||[];$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row"><div><small>SCRIPT ROOM</small><h1>导入剧本，拆成镜头。</h1></div><span class="spacer"></span>${button('导入剧本 TXT / DOCX','import-script','','primary')}${button('导出剧本 TXT','export-script')}</div><div class="split"><section class="section"><div class="row wrap">${button('全文','episode-select',`data-id="all"`,'active')}${eps.map(e=>button(E(e.name),'episode-select',`data-id="${e.id}"`)).join('')}${button('＋ 分集','add-episode')}</div><div style="margin-top:16px"><textarea class="script-text" id="scriptEditor" data-field="script" placeholder="第1集\n1-1 日 内 客厅\n人物：…\n△动作描述\n人物：台词">${E(P.script)}</textarea></div><div class="row wrap" style="margin-top:16px">${button('本地拆分 · 预览','parse-script')}${button('AI 拆分镜头','ai-breakdown','','primary')}${button('同步剧本节点','sync-script')}${button('剧本生成','page','data-page="writing"','primary')}${button('朗读 / 停止','read-script')}</div></section><section class="section">${Breakdown.workspace(P)}<h3>创作约束</h3><div class="field"><label>题材</label><input data-setting="genre" value="${E(P.settings.genre||'悬疑奇幻')}"></div><div class="field"><label>单集字数</label><input data-setting="words" value="${E(P.settings.words||'700–1000 字')}"></div><div class="field"><label>写作要求</label><textarea data-setting="writing">${E(P.settings.writing||'合并连续△动作；人物语言一致；每集结尾设置钩子。')}</textarea></div><div class="notice">本地拆分保留动作、台词与场次；AI 拆镜通过已连接的生成账号执行，提交前会显示账号和拆分范围。</div></section></div></div>`)}
