function assetsPage(){let list=P.assets.filter(a=>(filter==='all'||a.type===filter||a.kind===filter)&&(!search||[a.name,a.tags,a.description].join(' ').toLowerCase().includes(search.toLowerCase())));$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row wrap"><div><small>ASSET LIBRARY</small><p id="assetSyncStatus" class="muted">登录后，资产预览会同步供管理员按账号查看。</p><h1>每个角色，始终如一。</h1></div><span class="spacer"></span>${button('↑ 上传媒体','upload','','primary')}${button('＋ 资产生成任务','asset-task')}${button('对比候选图','compare-assets')}${button('录制配音','record-audio')}</div><div class="row wrap" style="margin:20px 0">${['all','角色','场景','道具','video','audio'].map(t=>button({all:'全部',video:'视频',audio:'音频'}[t]||t,'filter',`data-type="${t}"`,filter===t?'active':'')).join('')}<input class="search" placeholder="搜索名称、标签" id="assetSearch" value="${E(search)}" aria-label="搜索资产"></div><div class="asset-grid">${list.map(a=>`<article class="asset-card"><div class="asset-preview">${mediaHTML(a,true)}</div><h3>${E(a.name)} ${a.adminLocked?'🔒 管理员锁定':a.locked?'🔒':''}</h3>${a.kind==='image'?`<label class="row"><input class="compare-check" type="checkbox" value="${a.id}" style="width:auto"><small>选择对比</small></label>`:''}<small>${E(a.type)} · ${a.kind} ${a.width?`· ${a.width}×${a.height}`:''} ${a.duration?'· '+a.duration.toFixed(1)+'秒':''}</small><p class="tags">${E(a.tags||'未添加标签')}</p><div class="row wrap">${button('编辑','edit-asset',`data-id="${a.id}"`)}${button('→ 时间线','asset-timeline',`data-id="${a.id}"`)}${button('↓','download-asset',`data-id="${a.id}"`)}</div></article>`).join('')||'<div class="empty">还没有匹配的资产。上传自己的图片、视频或音频开始创作。</div>'}</div><div class="notice">角色锁定用于固定参考资产与提示词，防止本地编辑误改。跨镜头实际生成一致性还取决于接入模型的参考图能力。</div></div>`)}
