async function importMedia(files,{videoReferences=false}={}){if(uiBusy)return;uiBusy=true;const projectId=P.id;checkpoint();const failures=[];try{for(const f of files){try{if(P.id!==projectId)break;if(f.size>50*1024*1024){toast(f.name+' 超过 50MB，暂不支持');continue}let kind=f.type.split('/')[0];if(!['image','video','audio'].includes(kind)||!/^((image\/(png|jpeg|webp|gif))|(video\/(mp4|webm|quicktime))|(audio\/(mpeg|mp3|wav|x-wav|ogg|webm|mp4|x-m4a|m4a|aac|flac)))$/i.test(f.type)){toast('不支持的文件：'+f.name);continue}toast('正在导入 '+f.name);let src=await new Promise((res,rej)=>{let r=new FileReader;r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(f)});let a={id:C.uid(),name:f.name,kind,type:kind==='image'?'角色':kind==='video'?'视频':'音频',src,created:Date.now(),locked:false,tags:'',description:''};if(kind==='image'){let im=await loadImage(src);a.width=im.width;a.height=im.height}else{let el=document.createElement(kind);el.src=src;await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error(f.name+' 读取超时')),10000);el.onloadedmetadata=()=>{clearTimeout(timer);res()};el.onerror=()=>{clearTimeout(timer);rej(Error(f.name+' 无法解码'))}});a.duration=Number.isFinite(el.duration)?el.duration:5;if(kind==='video'){a.width=el.videoWidth;a.height=el.videoHeight}el.removeAttribute('src');el.load()}P.assets.push(a);if(videoReferences&&kind==='image')SB.appendVideoReferences(P,[a.id]);queueSave()}catch(error){failures.push(f.name+'：'+error.message)}}await flush();render();toast(failures.length?'已导入可用媒体，失败 '+failures.length+' 张：'+failures.join('；'):'媒体已导入当前项目')}catch(e){toast('部分媒体导入失败：'+e.message);queueSave();render()}finally{uiBusy=false}}
